-- name: GetIssueThread :one
SELECT to_jsonb(t)::jsonb AS data FROM issue_threads t WHERE id = CAST(@id AS text)::uuid AND archived_at IS NULL;
-- name: ListIssueThread :many
SELECT to_jsonb(t)::jsonb AS data FROM issue_threads t WHERE (sqlc.arg(include_archived)::boolean OR archived_at IS NULL) AND to_jsonb(t) @> CAST(@filter AS jsonb) ORDER BY created_at DESC, id LIMIT CAST(@page_limit AS int) OFFSET CAST(@page_offset AS int);
-- name: PutIssueThread :one
INSERT INTO issue_threads (id, project_id, repo, number, issue_url, title, instance_id, thread_id, model, effort) VALUES (COALESCE(NULLIF(CAST(@payload AS jsonb)->>'id','')::uuid, gen_random_uuid()), NULLIF(CAST(@payload AS jsonb)->>'project_id','')::uuid, CAST(@payload AS jsonb)->>'repo', (CAST(@payload AS jsonb)->>'number')::int, CAST(@payload AS jsonb)->>'issue_url', COALESCE(CAST(@payload AS jsonb)->>'title',''), NULLIF(CAST(@payload AS jsonb)->>'instance_id','')::uuid, CAST(@payload AS jsonb)->>'thread_id', COALESCE(CAST(@payload AS jsonb)->>'model',''), COALESCE(CAST(@payload AS jsonb)->>'effort','')) ON CONFLICT (id) DO UPDATE SET project_id = EXCLUDED.project_id, repo = EXCLUDED.repo, number = EXCLUDED.number, issue_url = EXCLUDED.issue_url, title = EXCLUDED.title, instance_id = EXCLUDED.instance_id, thread_id = EXCLUDED.thread_id, model = EXCLUDED.model, effort = EXCLUDED.effort, updated_at = now() WHERE issue_threads.archived_at IS NULL RETURNING to_jsonb(issue_threads)::jsonb AS data;
-- name: ArchiveIssueThread :one
UPDATE issue_threads SET archived_at = now(), updated_at = now() WHERE id = CAST(@id AS text)::uuid AND archived_at IS NULL RETURNING to_jsonb(issue_threads)::jsonb AS data;
